'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var airy = require( './../lib/main.js' );


// FIXTURES //

var smallPositive = require( './fixtures/c/cephes/small_positive.json' );
var smallNegative = require( './fixtures/c/cephes/small_negative.json' );
var largePositive = require( './fixtures/c/cephes/large_positive.json' );
var largeNegative = require( './fixtures/c/cephes/large_negative.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof airy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the Airy functions Ai(x), Bi(x) and derivatives (large negative values)', function test( t ) {
	var expectedAip;
	var expectedBip;
	var expectedAi;
	var expectedBi;
	var delta;
	var out;
	var tol;
	var x;
	var i;

	expectedAi = largeNegative.Ai;
	expectedAip = largeNegative.Aip;
	expectedBi = largeNegative.Bi;
	expectedBip = largeNegative.Bip;
	x = largeNegative.x;
	for ( i = 0; i < x.length; i++ ) {
		out = airy( x[i] );
		if ( out[0] === expectedAi[i] ) {
			t.strictEqual( out[0], expectedAi[i], 'x: '+x[i]+', Ai: '+out[0]+', expected: '+expectedAi[i] );
		} else {
			delta = abs( out[0] - expectedAi[i] );
			tol = 3.0 * EPS * abs( expectedAi[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Ai: '+out[0]+'. E: '+expectedAi[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
		if ( out[1] === expectedAip[i] ) {
			t.strictEqual( out[1], expectedAip[i], 'x: '+x[i]+', Aip: '+out[1]+', expected: '+expectedAip[i] );
		} else {
			delta = abs( out[1] - expectedAip[i] );
			tol = 4.0 * EPS * abs( expectedAip[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Aip: '+out[1]+'. E: '+expectedAip[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
		if ( out[2] === expectedBi[i] ) {
			t.strictEqual( out[2], expectedBi[i], 'x: '+x[i]+', Bi: '+out[2]+', expected: '+expectedBi[i] );
		} else {
			delta = abs( out[2] - expectedBi[i] );
			tol = 3.0 * EPS * abs( expectedBi[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Bi: '+out[2]+'. E: '+expectedBi[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
		if ( out[3] === expectedBip[i] ) {
			t.strictEqual( out[3], expectedBip[i], 'x: '+x[i]+', Bip: '+out[3]+', expected: '+expectedBip[i] );
		} else {
			delta = abs( out[3] - expectedBip[i] );
			tol = 30.0 * EPS * abs( expectedBip[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Bip: '+out[3]+'. E: '+expectedBip[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});

tape( 'the function evaluates the Airy functions Ai(x), Bi(x) and derivatives (large negative positive values)', function test( t ) {
	var expectedAip;
	var expectedBip;
	var expectedAi;
	var expectedBi;
	var relTol;
	var absTol;
	var delta;
	var tol;
	var out;
	var x;
	var i;

	expectedAi = largePositive.Ai;
	expectedAip = largePositive.Aip;
	expectedBi = largePositive.Bi;
	expectedBip = largePositive.Bip;
	x = largePositive.x;
	for ( i = 0; i < x.length; i++ ) {
		out = airy( x[i] );
		if ( out[0] === expectedAi[i] ) {
			t.strictEqual( out[0], expectedAi[i], 'x: '+x[i]+', Ai: '+out[0]+', expected: '+expectedAi[i] );
		} else {
			delta = abs( out[0] - expectedAi[i] );
			relTol = EPS * abs( expectedAi[i] );
			absTol = 1e-8 * EPS;
			t.strictEqual( delta <= relTol || delta <= absTol, true, 'within tolerance. x: '+x[i]+'. Ai: '+out[0]+'. E: '+expectedAi[i]+'. Δ: '+delta+'. relTol: '+relTol+'. absTol: '+absTol+'.' );
		}
		if ( out[1] === expectedAip[i] ) {
			t.strictEqual( out[1], expectedAip[i], 'x: '+x[i]+', Aip: '+out[1]+', expected: '+expectedAip[i] );
		} else {
			delta = abs( out[1] - expectedAip[i] );
			relTol = EPS * abs( expectedAip[i] );
			absTol = 1e-8 * EPS;
			t.strictEqual( delta <= relTol || delta <= absTol, true, 'within tolerance. x: '+x[i]+'. Aip: '+out[0]+'. E: '+expectedAip[i]+'. Δ: '+delta+'. relTol: '+relTol+'. absTol: '+absTol+'.' );
		}
		if ( out[2] === expectedBi[i] ) {
			t.strictEqual( out[2], expectedBi[i], 'x: '+x[i]+', Bi: '+out[2]+', expected: '+expectedBi[i] );
		} else {
			delta = abs( out[2] - expectedBi[i] );
			tol = 100.0 * EPS * abs( expectedBi[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Bi: '+out[2]+'. E: '+expectedBi[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
		if ( out[3] === expectedBip[i] ) {
			t.strictEqual( out[3], expectedBip[i], 'x: '+x[i]+', Bip: '+out[3]+', expected: '+expectedBip[i] );
		} else {
			delta = abs( out[3] - expectedBip[i] );
			tol = 100.0 * EPS * abs( expectedBip[i] );
			t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x[i]+'. Bip: '+out[3]+'. E: '+expectedBip[i]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});

