tape( 'the function returns correct values if provided `0.0`', function test( t ) {
	var v = airy( 0.0 );
	t.strictEqual( v[0], 0.355028053887817, 'returns expected value' );
	t.strictEqual( v[1], -0.258819403792807, 'returns expected value' );
	t.strictEqual( v[2], 0.6149266274460002, 'returns expected value' );
	t.strictEqual( v[3], 0.44828835735382666, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = airy( NaN );
	t.strictEqual( isnan( v[0] ), true, 'returns expected value' );
	t.strictEqual( isnan( v[1] ), true, 'returns expected value' );
	t.strictEqual( isnan( v[2] ), true, 'returns expected value' );
	t.strictEqual( isnan( v[3] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns correct values if provided `+infinity`', function test( t ) {
	var v = airy( PINF );
	t.strictEqual( v[0], 0.0, 'returns 0.0' );
	t.strictEqual( v[1], 0.0, 'returns 0.0' );
	t.strictEqual( v[2], PINF, 'returns positive infinity' );
	t.strictEqual( v[3], PINF, 'returns positive infinity' );
	t.end();
});

tape( 'the function returns correct values if provided `200.0`', function test( t ) {
	var v = airy( 200.0 );
	t.strictEqual( v[0], 0.0, 'returns 0.0' );
	t.strictEqual( v[1], 0.0, 'returns 0.0' );
	t.strictEqual( v[2], PINF, 'returns positive infinity' );
	t.strictEqual( v[3], PINF, 'returns positive infinity' );
	t.end();
});

